package dao; import dto.PostImageDTO; import util.DBConnection; import java.sql.*; import java.util.*;
public class PostImageDAO { public int insert(PostImageDTO x)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO post_image(post_id,image_name,image_path,image_order) VALUES(?,?,?,?)")){p.setLong(1,x.getPostId());p.setString(2,x.getImageName());p.setString(3,x.getImagePath());p.setInt(4,x.getImageOrder());return p.executeUpdate();}}
public List<PostImageDTO> selectByPostId(long id)throws Exception{List<PostImageDTO>a=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM post_image WHERE post_id=? ORDER BY image_order,image_id")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){while(r.next())a.add(map(r));}}return a;}
public PostImageDTO selectById(long id)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM post_image WHERE image_id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}} public int delete(long id)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM post_image WHERE image_id=?")){p.setLong(1,id);return p.executeUpdate();}} public int getMaxOrder(long id)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COALESCE(MAX(image_order),0) FROM post_image WHERE post_id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?r.getInt(1):0;}}}
private PostImageDTO map(ResultSet r)throws SQLException{PostImageDTO x=new PostImageDTO();x.setImageId(r.getLong("image_id"));x.setPostId(r.getLong("post_id"));x.setImageName(r.getString("image_name"));x.setImagePath(r.getString("image_path"));x.setImageOrder(r.getInt("image_order"));x.setCreatedAt(r.getTimestamp("created_at"));return x;}}
